package com.rumitx.app.tak;
import java.io.StringReader;import javax.xml.parsers.*;import org.w3c.dom.*;import org.xml.sax.InputSource;import java.util.UUID;
/** ATAK legacy GeoChat XML, with explicit radio-room routing and loop rejection. */
public final class GeoChatPacket {
 public static final String ROOM="RumiTX Radio";
 public static String incoming(String bridgeUid,String sender,String text,long now){String uid=bridgeUid+"-radio-"+Integer.toHexString(sender.hashCode()),id=UUID.randomUUID().toString();return "<event version=\"2.0\" uid=\"GeoChat."+CotXml.escape(uid)+".All Chat Rooms."+id+"\" type=\"b-t-f\" how=\"h-g-i-g-o\" time=\""+CotXml.utc(now)+"\" start=\""+CotXml.utc(now)+"\" stale=\""+CotXml.utc(now+86400000)+"\"><point lat=\"0\" lon=\"0\" hae=\"999999\" ce=\"999999\" le=\"999999\"/><detail><__chat id=\"All Chat Rooms\" messageId=\""+id+"\" chatroom=\"All Chat Rooms\" senderCallsign=\"Radio "+CotXml.escape(sender)+"\" groupOwner=\"false\"><chatgrp uid0=\""+CotXml.escape(uid)+"\" uid1=\"All Chat Rooms\" id=\"All Chat Rooms\"/></__chat><link uid=\""+CotXml.escape(uid)+"\" type=\"a-f-G-U-C-I\" relation=\"p-p\"/><remarks source=\"BAO.F.ATAK."+CotXml.escape(uid)+"\" time=\""+CotXml.utc(now)+"\">"+CotXml.escape(text)+"</remarks></detail></event>";}
 public static String[] outgoing(String xml,String bridgeUid)throws Exception {return outgoing(xml,bridgeUid,System.currentTimeMillis());}
 public static String[] outgoing(String xml,String bridgeUid,long now)throws Exception {if(xml.length()>60000||xml.toUpperCase(java.util.Locale.US).contains("<!DOCTYPE")||xml.toUpperCase(java.util.Locale.US).contains("<!ENTITY"))return null;DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setExpandEntityReferences(false);Document d=f.newDocumentBuilder().parse(new InputSource(new StringReader(xml)));Element e=d.getDocumentElement();String uid=e.getAttribute("uid");if(!"event".equals(e.getTagName())||!"b-t-f".equals(e.getAttribute("type"))||uid.isEmpty()||uid.length()>1024||uid.startsWith("GeoChat."+bridgeUid))return null;try{if(java.time.Instant.parse(e.getAttribute("stale")).toEpochMilli()<=now)return null;}catch(Exception badTime){return null;}NodeList chats=e.getElementsByTagName("__chat"),remarks=e.getElementsByTagName("remarks");if(chats.getLength()!=1||remarks.getLength()!=1)return null;Element chat=(Element)chats.item(0),r=(Element)remarks.item(0);if(!ROOM.equals(chat.getAttribute("chatroom"))&&!bridgeUid.equals(chat.getAttribute("id"))&&!bridgeUid.equals(r.getAttribute("to")))return null;String text=r.getTextContent();if(text==null||text.trim().isEmpty()||text.length()>120)return null;return new String[]{uid,text};}
}
